// Next.js API route support: https://nextjs.org/docs/api-routes/introduction
import type { NextApiRequest, NextApiResponse } from 'next'

type Data = {
  name: string
}

export default function handler(
  req: NextApiRequest,
  res: NextApiResponse<Data>
) {
  res.status(200).json({ name: 'John Doe' })
}

import { interpret } from "xstate";
import {
  getIsLoggedIn,
  getIsLoggedOut,
  getUserUsername,
  globalStateMachine,
} from "../globalState.machine";

/**
 * This file is an example of unit testing a machine. This
 * is not always recommended - but if you like unit tests
 * this setup will serve you well.
 */
describe("globalStateMachine", () => {
  describe("When there is a username in localStorage", () => {
    it("Should log you in automatically", () => {
      /**
       * Monkey patch window and localStorage
       */
      global.window = {} as any;
      global.localStorage = { getItem: () => "username" } as any;

      const service = interpret(globalStateMachine).start();

      /**
       * We test our code using our selectors declared
       * alongside the machine
       */
      expect(getIsLoggedIn(service.state)).toEqual(true);
      expect(getUserUsername(service.state)).toEqual("username");
    });
  });

  describe("When there is no username in localStorage", () => {
    it("Should keep you logged out", () => {
      global.window = {} as any;
      global.localStorage = { getItem: () => null } as any;

      const service = interpret(globalStateMachine).start();

      expect(getIsLoggedOut(service.state)).toEqual(true);
    });
  });

  it("Should allow you to log in when logged out", () => {
    const setItemMock = jest.fn();
    global.window = {} as any;
    global.localStorage = { getItem: () => null, setItem: setItemMock } as any;

    const service = interpret(globalStateMachine).start();

    service.send({
      type: "LOG_IN",
      username: "new-username",
      password: "pw",
    });

    expect(getIsLoggedIn(service.state)).toEqual(true);
    /**
     * Expect the second parameter of the first call
     * of localStorage.setItem to equal 'new-username'
     */
    expect(setItemMock.mock.calls[0][1]).toEqual("new-username");
    /**
     * Expect the new username to be in context
     */
    expect(getUserUsername(service.state)).toEqual("new-username");
  });

  it("Should allow you to log out when logged in", () => {
    const removeItemMock = jest.fn();
    global.window = {} as any;
    global.localStorage = {
      getItem: () => "username",
      removeItem: removeItemMock,
    } as any;

    const service = interpret(globalStateMachine).start();

    service.send({
      type: "LOG_OUT",
    });

    expect(getIsLoggedOut(service.state)).toEqual(true);
    /**
     * Expect that the username has been removed from localStorage
     */
    expect(removeItemMock).toHaveBeenCalled();
    /**
     * Expect that the username has been removed from context
     */
    expect(getUserUsername(service.state)).toEqual(null);
  });
});

import { assign } from "xstate";
import { createModel } from "xstate/lib/model";
import { createXStateContext } from "../lib/createXStateContext";

/**
 * Create a typesafe model for your app's global state
 */
export const globalStateModel = createModel(
  {
    username: null as string | null,
  },
  {
    events: {
      LOG_IN: (username: string, password: string) => ({ username, password }),
      LOG_OUT: () => ({}),
    },
  },
);

/**
 * Create a machine based on the model above
 *
 * This also adds a check based on whether we're server side
 * or client side, because for this example we use localStorage
 * to store whether the client is logged in or not
 */
export const globalStateMachine = globalStateModel.createMachine({
  id: "globalState",
  initial: "checkingIfServerSide",
  states: {
    checkingIfServerSide: {
      always: [
        {
          cond: () => {
            return typeof window === "undefined";
          },
          target: "complete",
        },
        {
          target: "checkingIfLoggedIn",
        },
      ],
    },
    checkingIfLoggedIn: {
      always: [
        {
          cond: () => {
            return Boolean(localStorage.getItem(GLOBAL_STATE_KEY));
          },
          actions: assign((context, event) => {
            return {
              username: localStorage.getItem(GLOBAL_STATE_KEY),
            };
          }),
          target: "loggedIn",
        },
        {
          target: "loggedOut",
        },
      ],
    },
    loggedIn: {
      exit: [
        () => localStorage.removeItem(GLOBAL_STATE_KEY),
        assign((ctx) => {
          return {
            username: null,
          };
        }),
      ],
      on: {
        LOG_OUT: {
          target: "loggedOut",
        },
      },
    },
    loggedOut: {
      on: {
        LOG_IN: {
          target: "loggedIn",
          actions: [
            (ctx, event) => {
              localStorage.setItem(GLOBAL_STATE_KEY, event.username);
            },
            assign((context, event) => {
              return {
                username: event.username,
              };
            }),
          ],
        },
      },
    },
    complete: {
      type: "final",
    },
  },
});

export const [
  GlobalStateProvider,
  useGlobalStateService,
  useSelectedGlobalState,
  createGlobalStateSelector,
] = createXStateContext(globalStateMachine);

/** Selectors */
export const getUserUsername = createGlobalStateSelector(
  (state) => state.context.username,
);

export const getIsLoggedIn = createGlobalStateSelector((state) =>
  state.matches("loggedIn"),
);

export const getIsLoggedOut = createGlobalStateSelector((state) =>
  state.matches("loggedOut"),
);

const GLOBAL_STATE_KEY = "GLOBAL_STATE_KEY";

import React from "react";
import {
  getIsLoggedIn,
  getIsLoggedOut,
  getUserUsername,
  useGlobalStateService,
  useSelectedGlobalState,
} from "../machines/globalState.machine";

export const Layout: React.FC = ({ children }) => {
  /**
   * Grab the global state service
   */
  const globalStateService = useGlobalStateService();

  /**
   * Grab the selected information. Instead of re-rendering
   * on every state change, this component will only re-render
   * whenever the value of these items change
   */
  const username = useSelectedGlobalState(getUserUsername);
  const isLoggedIn = useSelectedGlobalState(getIsLoggedIn);
  const isLoggedOut = useSelectedGlobalState(getIsLoggedOut);

  return (
    <div>
      <nav
        style={{
          display: "flex",
          justifyContent: "space-between",
          padding: "1rem",
        }}
      >
        <div>{username}</div>
        {isLoggedIn && (
          <button
            onClick={() =>
              globalStateService.send({
                type: "LOG_OUT",
              })
            }
          >
            Log Out
          </button>
        )}
        {isLoggedOut && (
          <button
            onClick={() => {
              globalStateService.send({
                type: "LOG_IN",
                password: "password",
                username: "username",
              });
            }}
          >
            Log In
          </button>
        )}
      </nav>
      <main>{children}</main>
    </div>
  );
};

import { useSelector } from "@xstate/react";
import { createContext, useContext as useReactContext } from "react";
import { InterpreterFrom, StateFrom, StateMachine } from "xstate";

/**
 * Creates a global state wrapper you can use
 * to pass XState through your app
 */
export function createXStateContext<
  TMachine extends StateMachine<any, any ,any ,any ,any ,any ,any>,
>(machine: TMachine) {
  /**
   * Creates a React context containing an ActorRef
   */
  const context = createContext<InterpreterFrom<TMachine> | null>(null);
  /**
   * By default, the display name for this context
   * is the machine's id.
   */
  context.displayName = machine.id;

  /**
   * Grabs the running service directly from the context,
   * useful for when you want to send events to the service.
   */
  const useContext = () => {
    const ctx = useReactContext(context);
    if (!ctx) {
      throw new Error(
        `use${machine.id}Context must be used inside ${machine.id}Provider`,
      );
    }
    return ctx;
  };

  /**
   * Grab a selected portion of the running service using
   * xstate/react's useSelector
   *
   * https://xstate.js.org/docs/packages/xstate-react/#useselector-actor-selector-compare-getsnapshot
   */
  const useSelectedContext = <T>(
    selector: (state: StateFrom<TMachine>) => T,
  ): T => {
    const service = useContext();
    return useSelector(service, selector);
  };

  /**
   * Create a selector which you can later pass in to
   * useSelectedContext above. This function does nothing
   * except provide a useful wrapper for type definitions
   */
  const createSelector = <T>(selector: (state: StateFrom<TMachine>) => T) => {
    return selector;
  };

  /**
   * Returns a tuple of the items above so you can freely
   * name them based on context
   */
  return [
    context.Provider,
    useContext,
    useSelectedContext,
    createSelector,
  ] as const;
}

import "../styles/globals.css";
import type { AppProps } from "next/app";
import { useInterpret } from "@xstate/react";
import {
  globalStateMachine,
  GlobalStateProvider,
} from "../machines/globalState.machine";
import { Layout } from "../lib/Layout";

function MyApp({ Component, pageProps }: AppProps) {
  /**
   * We use useInterpret, not useMachine. If we were to use
   * useMachine, the whole app would re-render whenever the
   * globalStateService changed state
   */
  const globalStateService = useInterpret(globalStateMachine);

  return (
    <GlobalStateProvider value={globalStateService}>
      <Layout>
        <Component {...pageProps} />
      </Layout>
    </GlobalStateProvider>
  );
}
export default MyApp;
